create or replace function public.accept_terms_of_service(accepted_version text)
returns public.terms_acceptances
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  current_terms_version constant text := '2026-08-05';
  result_acceptance public.terms_acceptances%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required to accept the Terms of Service.';
  end if;

  if btrim(coalesce(accepted_version, '')) <> current_terms_version then
    raise exception 'The Terms of Service version is no longer current. Reload and review the latest version.';
  end if;

  insert into public.terms_acceptances (profile_id, terms_version, accepted_at)
  values (auth.uid(), current_terms_version, timezone('utc', now()))
  on conflict (profile_id) do update
    set terms_version = excluded.terms_version,
        accepted_at = excluded.accepted_at
  returning * into result_acceptance;

  return result_acceptance;
end;
$$;

create or replace function public.add_project_track(
  target_project_id uuid,
  target_song_id uuid,
  target_version_id uuid default null,
  target_title text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  current_user_id uuid := auth.uid();
  next_track_number integer;
  new_track_id uuid;
  song_title text;
begin
  if not public.can_edit_collaboration_project(target_project_id, current_user_id) then
    raise exception 'You cannot edit the track list for this project.';
  end if;

  select title into song_title
  from public.songs
  where id = target_song_id
    and (
      owner_id = current_user_id
      or exists (
        select 1
        from public.song_versions
        where song_id = target_song_id
          and collaboration_project_id = target_project_id
      )
    );

  if song_title is null then
    raise exception 'Song not found or unavailable.';
  end if;

  if target_version_id is not null and not exists (
    select 1
    from public.song_versions
    where id = target_version_id
      and song_id = target_song_id
  ) then
    raise exception 'The selected version does not belong to this song.';
  end if;

  select coalesce(max(track_number), 0) + 1
  into next_track_number
  from public.collaboration_project_tracks
  where project_id = target_project_id;

  insert into public.collaboration_project_tracks (
    project_id,
    song_id,
    active_version_id,
    track_title,
    track_number,
    created_by
  )
  values (
    target_project_id,
    target_song_id,
    target_version_id,
    coalesce(nullif(btrim(target_title), ''), song_title),
    next_track_number,
    current_user_id
  )
  returning id into new_track_id;

  if target_version_id is not null then
    update public.song_versions
    set
      collaboration_project_id = target_project_id,
      collaboration_track_id = new_track_id,
      sharing_mode = 'project_members'
    where id = target_version_id;
  end if;

  insert into public.collaboration_activity (
    project_id,
    actor_id,
    activity_type,
    entity_type,
    entity_id,
    metadata
  )
  values (
    target_project_id,
    current_user_id,
    'track_added',
    'track',
    new_track_id,
    jsonb_build_object('track_number', next_track_number)
  );

  return new_track_id;
end;
$$;

create or replace function public.block_profile(target_profile_id uuid)
returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  current_user_id uuid := auth.uid();
  shared_project_count integer;
begin
  if current_user_id is null then
    raise exception 'Authentication required.';
  end if;

  if current_user_id = target_profile_id then
    raise exception 'You cannot block yourself.';
  end if;

  if not exists (
    select 1 from public.profiles where id = target_profile_id
  ) then
    raise exception 'Profile not found.';
  end if;

  insert into public.profile_blocks (blocker_id, blocked_id)
  values (current_user_id, target_profile_id)
  on conflict do nothing;

  delete from public.follows
  where (follower_id = current_user_id and followed_id = target_profile_id)
    or (follower_id = target_profile_id and followed_id = current_user_id);

  delete from public.profile_mutes
  where muter_id = current_user_id
    and muted_id = target_profile_id;

  select count(distinct mine.project_id)::integer
  into shared_project_count
  from public.collaboration_project_members as mine
  join public.collaboration_project_members as theirs
    on theirs.project_id = mine.project_id
  where mine.profile_id = current_user_id
    and mine.membership_status = 'accepted'
    and theirs.profile_id = target_profile_id
    and theirs.membership_status = 'accepted';

  return coalesce(shared_project_count, 0);
end;
$$;

