create or replace function public.change_project_member_role(
  target_project_id uuid,
  target_profile_id uuid,
  next_role text
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  current_user_id uuid := auth.uid();
  actor_role text := public.collaboration_member_role(target_project_id, current_user_id);
  current_target_role text := public.collaboration_member_role(target_project_id, target_profile_id);
begin
  if actor_role not in ('owner', 'admin') then
    raise exception 'You cannot manage project roles.';
  end if;

  if next_role not in ('admin', 'editor', 'contributor', 'reviewer', 'viewer') then
    raise exception 'Unsupported project role.';
  end if;

  if current_target_role is null or current_target_role = 'owner' then
    raise exception 'The selected role cannot be changed.';
  end if;

  if actor_role = 'admin' and (
    current_target_role = 'admin'
    or next_role = 'admin'
  ) then
    raise exception 'Only the owner can manage admin roles.';
  end if;

  update public.collaboration_project_members
  set role = next_role
  where project_id = target_project_id
    and profile_id = target_profile_id
    and membership_status = 'accepted';

  insert into public.notifications (recipient_id, actor_id, type, project_id)
  values (target_profile_id, current_user_id, 'project_role_changed', target_project_id);

  insert into public.collaboration_activity (
    project_id,
    actor_id,
    activity_type,
    entity_type,
    entity_id,
    metadata
  )
  values (
    target_project_id,
    current_user_id,
    'role_changed',
    'profile',
    target_profile_id,
    jsonb_build_object('previous_role', current_target_role, 'role', next_role)
  );
end;
$$;

create or replace function public.compact_post_card_waveform(
  target_waveform jsonb,
  max_buckets integer default 320
)
returns jsonb
language plpgsql
immutable
set search_path = public, pg_temp
as $$
declare
  source_peaks jsonb;
  compact_peaks jsonb := '[]'::jsonb;
  source_count integer;
  bucket_limit integer := greatest(1, max_buckets);
  bucket_stride integer;
  bucket_index integer;
begin
  if target_waveform is null then
    return null;
  end if;

  source_peaks := case
    when jsonb_typeof(target_waveform) = 'object' then target_waveform -> 'peaks'
    else target_waveform
  end;

  if jsonb_typeof(source_peaks) <> 'array' then
    return target_waveform;
  end if;

  source_count := jsonb_array_length(source_peaks);
  if source_count <= bucket_limit then
    return target_waveform;
  end if;

  bucket_stride := greatest(1, ceil(source_count::numeric / bucket_limit)::integer);
  for bucket_index in 0..(source_count - 1) by bucket_stride loop
    compact_peaks := compact_peaks || jsonb_build_array(source_peaks -> bucket_index);
  end loop;

  if jsonb_typeof(target_waveform) = 'object' then
    return jsonb_set(
      jsonb_set(target_waveform, '{peaks}', compact_peaks, true),
      '{bucketCount}',
      to_jsonb(jsonb_array_length(compact_peaks)),
      true
    );
  end if;

  return compact_peaks;
end;
$$;

create or replace function public.create_collaboration_project(
  project_title text,
  project_kind text,
  project_description text default null,
  project_visibility text default 'private'
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  current_user_id uuid := auth.uid();
  new_project_id uuid;
  new_conversation_id uuid;
begin
  if current_user_id is null then
    raise exception 'Authentication required.';
  end if;

  if project_kind not in ('single', 'ep', 'album', 'loose_collection') then
    raise exception 'Unsupported project type.';
  end if;

  if project_visibility not in ('private', 'members_only', 'link_invite') then
    raise exception 'Unsupported project visibility.';
  end if;

  if not (char_length(btrim(project_title)) between 1 and 160) then
    raise exception 'Project title must contain between 1 and 160 characters.';
  end if;

  if (
    select count(*)
    from public.collaboration_projects
    where owner_id = current_user_id
      and archived_at is null
  ) >= 25 then
    raise exception 'The active collaboration project quota has been reached.';
  end if;

  insert into public.collaboration_projects (
    owner_id,
    project_type,
    title,
    description,
    visibility,
    status
  )
  values (
    current_user_id,
    project_kind,
    btrim(project_title),
    nullif(btrim(project_description), ''),
    project_visibility,
    'planning'
  )
  returning id into new_project_id;

  insert into public.collaboration_project_members (
    project_id,
    profile_id,
    role,
    membership_status,
    invited_by,
    joined_at
  )
  values (
    new_project_id,
    current_user_id,
    'owner',
    'accepted',
    current_user_id,
    timezone('utc', now())
  );

  insert into public.conversations (kind, project_id)
  values ('project', new_project_id)
  returning id into new_conversation_id;

  insert into public.conversation_members (conversation_id, profile_id)
  values (new_conversation_id, current_user_id);

  insert into public.collaboration_activity (
    project_id,
    actor_id,
    activity_type,
    entity_type,
    entity_id
  )
  values (
    new_project_id,
    current_user_id,
    'project_created',
    'project',
    new_project_id
  );

  return new_project_id;
end;
$$;

create or replace function public.create_comment_notification()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  target_post_owner_id uuid;
  parent_author_id uuid;
begin
  select owner_id
  into target_post_owner_id
  from public.posts
  where id = new.post_id;

  if new.parent_comment_id is not null then
    select author_id
    into parent_author_id
    from public.comments
    where id = new.parent_comment_id;
  end if;

  if target_post_owner_id is not null and target_post_owner_id <> new.author_id then
    insert into public.notifications (recipient_id, actor_id, type, post_id, comment_id)
    values (target_post_owner_id, new.author_id, 'comment', new.post_id, new.id);
  end if;

  if parent_author_id is not null and parent_author_id <> new.author_id and parent_author_id <> target_post_owner_id then
    insert into public.notifications (recipient_id, actor_id, type, post_id, comment_id)
    values (parent_author_id, new.author_id, 'comment_reply', new.post_id, new.id);
  end if;

  return new;
end;
$$;

create or replace function public.create_direct_conversation(other_profile_id uuid)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  current_user_id uuid := auth.uid();
  existing_conversation_id uuid;
  new_conversation_id uuid;
begin
  if current_user_id is null then
    raise exception 'Authentication required.';
  end if;

  if not public.can_message_profile(current_user_id, other_profile_id) then
    raise exception 'This account is not accepting direct messages from you.';
  end if;

  select member.conversation_id
  into existing_conversation_id
  from public.conversation_members as member
  join public.conversation_members as counterpart
    on counterpart.conversation_id = member.conversation_id
  join public.conversations as conversation
    on conversation.id = member.conversation_id
  where conversation.kind = 'direct'
    and member.profile_id = current_user_id
    and counterpart.profile_id = other_profile_id
  limit 1;

  if existing_conversation_id is not null then
    return existing_conversation_id;
  end if;

  insert into public.conversations (kind)
  values ('direct')
  returning id into new_conversation_id;

  insert into public.conversation_members (conversation_id, profile_id)
  values
    (new_conversation_id, current_user_id),
    (new_conversation_id, other_profile_id);

  return new_conversation_id;
end;
$$;

create or replace function public.create_message_reference_attachment(
  target_message_id uuid,
  target_attachment_type text,
  target_id uuid
)
returns public.message_attachments
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  current_user_id uuid := auth.uid();
  target_message public.messages%rowtype;
  reference_title text;
  result_attachment public.message_attachments%rowtype;
begin
  if current_user_id is null then
    raise exception 'Authentication required.';
  end if;

  if target_attachment_type not in (
    'project_reference',
    'post_reference',
    'song_version_reference'
  ) then
    raise exception 'Unsupported message reference type.';
  end if;

  select *
  into target_message
  from public.messages
  where id = target_message_id
    and sender_id = current_user_id
    and deleted_at is null;

  if target_message.id is null
    or not public.is_conversation_member(target_message.conversation_id, current_user_id) then
    raise exception 'Message not found.';
  end if;

  if target_attachment_type = 'project_reference' then
    select title into reference_title
    from public.collaboration_projects
    where id = target_id
      and archived_at is null;

    if reference_title is null or exists (
      select 1
      from public.conversation_members as member
      where member.conversation_id = target_message.conversation_id
        and not public.can_view_collaboration_project(target_id, member.profile_id)
    ) then
      raise exception 'Every conversation member must be able to view this project.';
    end if;
  elsif target_attachment_type = 'post_reference' then
    select title into reference_title
    from public.posts
    where id = target_id;

    if reference_title is null or exists (
      select 1
      from public.conversation_members as member
      where member.conversation_id = target_message.conversation_id
        and not public.can_view_post(target_id, member.profile_id)
    ) then
      raise exception 'Every conversation member must be able to view this release.';
    end if;
  else
    select song.title || ' · ' || version.version_label
    into reference_title
    from public.song_versions as version
    join public.songs as song on song.id = version.song_id
    where version.id = target_id;

    if reference_title is null or exists (
      select 1
      from public.conversation_members as member
      where member.conversation_id = target_message.conversation_id
        and not public.can_profile_view_song_version(target_id, member.profile_id)
    ) then
      raise exception 'Every conversation member must be able to view this song version.';
    end if;
  end if;

  insert into public.message_attachments (
    message_id,
    owner_id,
    attachment_type,
    post_id,
    project_id,
    song_version_id,
    filename,
    mime_type,
    bytes
  )
  values (
    target_message_id,
    current_user_id,
    target_attachment_type,
    case when target_attachment_type = 'post_reference' then target_id else null end,
    case when target_attachment_type = 'project_reference' then target_id else null end,
    case when target_attachment_type = 'song_version_reference' then target_id else null end,
    reference_title,
    'application/x-mxshare-reference',
    0
  )
  returning * into result_attachment;

  return result_attachment;
end;
$$;

create or replace function public.create_post_heart_notification()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  target_owner_id uuid;
begin
  select owner_id
  into target_owner_id
  from public.posts
  where id = new.post_id;

  if target_owner_id is not null and target_owner_id <> new.profile_id then
    insert into public.notifications (recipient_id, actor_id, type, post_id)
    values (target_owner_id, new.profile_id, 'post_heart', new.post_id);
  end if;

  return new;
end;
$$;

create or replace function public.create_share_link(
  target_kind text,
  target_entity_id uuid,
  target_permission text default 'view',
  target_expires_at timestamptz default null,
  target_max_uses integer default null
)
returns table (share_link_id uuid, share_token text)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  current_user_id uuid := auth.uid();
  raw_token text;
  new_link_id uuid;
  can_create boolean := false;
begin
  if current_user_id is null then
    raise exception 'Authentication required.';
  end if;

  if target_kind = 'post' then
    can_create := exists (
      select 1 from public.posts where id = target_entity_id and owner_id = current_user_id
    );
  elsif target_kind = 'collaboration_project' then
    can_create := public.can_manage_collaboration_members(target_entity_id, current_user_id);
  elsif target_kind = 'song_version' then
    can_create := exists (
      select 1 from public.song_versions where id = target_entity_id and owner_id = current_user_id
    );
  else
    raise exception 'Unsupported share-link target.';
  end if;

  if not can_create then
    raise exception 'You cannot share this item.';
  end if;

  if (
    select count(*)
    from public.share_links
    where owner_id = current_user_id
      and target_type = target_kind
      and target_id = target_entity_id
      and is_active = true
  ) >= 10 then
    raise exception 'The active share-link quota for this item has been reached.';
  end if;

  raw_token := encode(extensions.gen_random_bytes(32), 'hex');

  insert into public.share_links (
    owner_id,
    target_type,
    target_id,
    token_hash,
    permission,
    expires_at,
    max_uses
  )
  values (
    current_user_id,
    target_kind,
    target_entity_id,
    encode(extensions.digest(raw_token, 'sha256'), 'hex'),
    target_permission,
    target_expires_at,
    target_max_uses
  )
  returning id into new_link_id;

  return query select new_link_id, raw_token;
end;
$$;

create or replace function public.create_single_post(
  target_song_id uuid,
  target_version_id uuid,
  target_title text,
  target_description text default null,
  target_artwork_asset_id uuid default null,
  target_visibility text default 'public'
)
returns public.posts
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  current_user_id uuid := auth.uid();
  created_post public.posts%rowtype;
begin
  if current_user_id is null then
    raise exception 'Authentication required.';
  end if;

  if target_visibility not in ('public', 'followers', 'unlisted', 'private') then
    raise exception 'Unsupported post visibility.';
  end if;

  if not exists (
    select 1
    from public.songs as song
    join public.song_versions as version on version.song_id = song.id
    where song.id = target_song_id
      and song.owner_id = current_user_id
      and version.id = target_version_id
  ) then
    raise exception 'The selected song version is not owned by the current user.';
  end if;

  if target_artwork_asset_id is not null and not exists (
    select 1
    from public.assets as asset
    where asset.id = target_artwork_asset_id
      and asset.owner_id = current_user_id
  ) then
    raise exception 'The selected artwork is not owned by the current user.';
  end if;

  insert into public.posts (
    owner_id,
    post_type,
    title,
    description,
    artwork_asset_id,
    visibility,
    is_published,
    published_at,
    activity_at
  )
  values (
    current_user_id,
    'single',
    coalesce(nullif(btrim(target_title), ''), 'Untitled single'),
    nullif(btrim(coalesce(target_description, '')), ''),
    target_artwork_asset_id,
    target_visibility,
    target_visibility <> 'private',
    case when target_visibility <> 'private' then timezone('utc', now()) else null end,
    timezone('utc', now())
  )
  returning *
  into created_post;

  insert into public.single_posts (post_id, song_id, featured_version_id)
  values (created_post.id, target_song_id, target_version_id);

  return created_post;
end;
$$;

create or replace function public.create_version_heart_notification()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  target_owner_id uuid;
begin
  select songs.owner_id
  into target_owner_id
  from public.song_versions
  join public.songs on songs.id = song_versions.song_id
  where song_versions.id = new.song_version_id;

  if target_owner_id is not null and target_owner_id <> new.profile_id then
    insert into public.notifications (recipient_id, actor_id, type, song_version_id)
    values (target_owner_id, new.profile_id, 'version_heart', new.song_version_id);
  end if;

  return new;
end;
$$;

create or replace function public.decline_project_invite(invite_token text)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  current_user_id uuid := auth.uid();
begin
  update public.collaboration_project_invites
  set status = 'declined'
  where invite_token_hash = encode(extensions.digest(invite_token, 'sha256'), 'hex')
    and status = 'pending'
    and (invited_profile_id is null or invited_profile_id = current_user_id);

  if not found then
    raise exception 'This invitation cannot be declined.';
  end if;
end;
$$;

create or replace function public.delete_message_attachment(target_attachment_id uuid)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  target_protected_asset_id uuid;
begin
  update public.message_attachments
  set deleted_at = timezone('utc', now())
  where id = target_attachment_id
    and owner_id = auth.uid()
    and deleted_at is null
  returning protected_asset_id into target_protected_asset_id;

  if not found then
    raise exception 'Attachment not found.';
  end if;

  return target_protected_asset_id;
end;
$$;

create or replace function public.delete_own_message(target_message_id uuid)
returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  updated_rows integer;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if exists (
    select 1
    from public.message_attachments
    where message_id = target_message_id
      and deleted_at is null
  ) then
    raise exception 'Delete the message attachments before deleting the message.';
  end if;

  update public.messages
  set
    body = '',
    deleted_at = timezone('utc', now()),
    edited_at = timezone('utc', now())
  where id = target_message_id
    and sender_id = auth.uid()
    and deleted_at is null;

  get diagnostics updated_rows = row_count;
  return updated_rows > 0;
end;
$$;

