create or replace function public.finalize_media_processing_job(
  job_id uuid,
  preview_asset_id uuid
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  current_user_id uuid := auth.uid();
  target_job public.media_processing_jobs%rowtype;
  preview_asset public.assets%rowtype;
  bucket_count integer;
begin
  if current_user_id is null then
    raise exception 'Authentication required.';
  end if;

  select *
  into target_job
  from public.media_processing_jobs
  where id = job_id
    and owner_id = current_user_id;

  if target_job.id is null then
    raise exception 'Processing job not found.';
  end if;

  if target_job.status not in ('ready', 'uploading_to_drive') then
    raise exception 'Processing job is not ready for finalization.';
  end if;

  select *
  into preview_asset
  from public.assets
  where id = preview_asset_id
    and owner_id = current_user_id;

  if preview_asset.id is null then
    raise exception 'Preview asset not found.';
  end if;

  if preview_asset.asset_type <> 'audio_preview' then
    raise exception 'Preview asset must be an audio preview.';
  end if;

  if preview_asset.mime_type <> 'audio/mpeg' then
    raise exception 'Preview asset must use audio/mpeg.';
  end if;

  if preview_asset.access_mode <> 'public' then
    raise exception 'Preview asset must already be public.';
  end if;

  if preview_asset.derived_from_asset_id is distinct from target_job.source_asset_id then
    raise exception 'Preview asset does not match the source asset.';
  end if;

  if target_job.waveform_data is null then
    raise exception 'Waveform data is missing.';
  end if;

  select coalesce(jsonb_array_length(target_job.waveform_data -> 'peaks'), 0)
  into bucket_count;

  if coalesce((target_job.waveform_data ->> 'version')::integer, 0) <> 1 or bucket_count <= 0 then
    raise exception 'Waveform data is invalid.';
  end if;

  if target_job.song_version_id is not null and not exists (
    select 1
    from public.song_versions
    join public.songs on songs.id = song_versions.song_id
    where song_versions.id = target_job.song_version_id
      and songs.owner_id = current_user_id
  ) then
    raise exception 'Linked song version is not owned by the current user.';
  end if;

  update public.assets
  set
    processing_job_id = target_job.id,
    preview_generation = 'automatic',
    waveform_peaks = target_job.waveform_data,
    waveform_version = 1,
    waveform_bucket_count = bucket_count,
    waveform_generated_at = timezone('utc', now()),
    codec = coalesce(codec, target_job.detected_codec),
    sample_rate_hz = coalesce(sample_rate_hz, target_job.sample_rate_hz),
    channels = coalesce(channels, target_job.channels),
    bit_rate_bps = coalesce(bit_rate_bps, target_job.bit_rate_bps)
  where id = preview_asset_id;

  if target_job.song_version_id is not null then
    update public.song_versions
    set
      preview_asset_id = preview_asset_id,
      updated_at = timezone('utc', now())
    where id = target_job.song_version_id;
  end if;

  update public.media_processing_jobs
  set
    status = 'completed',
    stage = 'Completed',
    progress = 100,
    ready_at = coalesce(ready_at, timezone('utc', now())),
    completed_at = timezone('utc', now()),
    updated_at = timezone('utc', now())
  where id = target_job.id;
end;
$$;

create or replace function public.follow_profile(target_profile_id uuid)
returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  current_user_id uuid := auth.uid();
  inserted_rows integer := 0;
begin
  if current_user_id is null then
    raise exception 'Authentication required.';
  end if;

  if current_user_id = target_profile_id then
    raise exception 'You cannot follow yourself.';
  end if;

  if public.is_profile_blocked_pair(current_user_id, target_profile_id) then
    raise exception 'This profile is unavailable.';
  end if;

  if not public.can_view_profile(target_profile_id, current_user_id) then
    raise exception 'Target profile not found.';
  end if;

  insert into public.follows (follower_id, followed_id)
  values (current_user_id, target_profile_id)
  on conflict do nothing;

  get diagnostics inserted_rows = row_count;

  if inserted_rows > 0 then
    insert into public.notifications (recipient_id, actor_id, type)
    values (target_profile_id, current_user_id, 'follow');
    return true;
  end if;

  return false;
end;
$$;

create or replace function public.get_admin_report_target_profile_id(target_report_id uuid)
returns uuid
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  target_report public.reports%rowtype;
  target_profile_id uuid;
begin
  if not public.is_app_admin(auth.uid(), 'moderator') then
    raise exception 'Administrator access required.';
  end if;

  select * into target_report
  from public.reports
  where id = target_report_id;

  if target_report.id is null then
    return null;
  end if;

  if target_report.target_type = 'profile' then
    target_profile_id := target_report.target_id;
  elsif target_report.target_type = 'post' then
    select owner_id into target_profile_id from public.posts where id = target_report.target_id;
  elsif target_report.target_type = 'comment' then
    select author_id into target_profile_id from public.comments where id = target_report.target_id;
  elsif target_report.target_type = 'message' then
    select sender_id into target_profile_id from public.messages where id = target_report.target_id;
  elsif target_report.target_type = 'project_invite' then
    select invited_by into target_profile_id
    from public.collaboration_project_invites where id = target_report.target_id;
  elsif target_report.target_type = 'share_link' then
    select owner_id into target_profile_id from public.share_links where id = target_report.target_id;
  end if;

  return target_profile_id;
end;
$$;

create or replace function public.get_current_profile_v2()
returns public.profiles
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  result_profile public.profiles%rowtype;
begin
  if auth.uid() is null then
    return null;
  end if;

  select profile.*
  into result_profile
  from public.profiles as profile
  where profile.id = auth.uid();

  if not found then
    return null;
  end if;

  select coalesce(privacy.private_location, result_profile.location)
  into result_profile.location
  from public.profile_privacy_settings as privacy
  where privacy.profile_id = result_profile.id;

  return result_profile;
end;
$$;

create or replace function public.get_profile_by_username_v2(target_username text)
returns public.profiles
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  result_profile public.profiles%rowtype;
  location_is_public boolean;
  hidden_location text;
begin
  select profile.*
  into result_profile
  from public.profiles as profile
  where lower(profile.username) = lower(regexp_replace(btrim(target_username), '^@+', ''))
  limit 1;

  if not found
    or not public.can_view_profile(result_profile.id, auth.uid()) then
    return null;
  end if;

  select
    coalesce(privacy.show_location, true),
    privacy.private_location
  into location_is_public, hidden_location
  from public.profile_privacy_settings as privacy
  where privacy.profile_id = result_profile.id;

  location_is_public := coalesce(location_is_public, true);

  if result_profile.id = auth.uid() then
    result_profile.location := coalesce(hidden_location, result_profile.location);
  elsif not location_is_public then
    result_profile.location := null;
  end if;

  return result_profile;
end;
$$;

create or replace function public.invite_project_member(
  target_project_id uuid,
  target_role text,
  target_profile_id uuid default null,
  target_email text default null,
  expires_in_days integer default 14
)
returns table (invite_id uuid, invite_token text)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  current_user_id uuid := auth.uid();
  actor_role text;
  raw_token text;
  new_invite_id uuid;
begin
  actor_role := public.collaboration_member_role(target_project_id, current_user_id);

  if actor_role not in ('owner', 'admin') then
    raise exception 'You cannot manage members for this project.';
  end if;

  if target_role not in ('admin', 'editor', 'contributor', 'reviewer', 'viewer') then
    raise exception 'Unsupported project role.';
  end if;

  if actor_role = 'admin' and target_role = 'admin' then
    raise exception 'Only the owner can assign the admin role.';
  end if;

  if target_profile_id is null and nullif(btrim(target_email), '') is null then
    raise exception 'Choose a profile or provide an email address.';
  end if;

  if target_profile_id = current_user_id then
    raise exception 'You are already a member of this project.';
  end if;

  if (
    select count(*)
    from public.collaboration_project_members
    where project_id = target_project_id
      and membership_status in ('invited', 'accepted')
  ) >= 25 then
    raise exception 'The project member quota has been reached.';
  end if;

  if target_profile_id is not null and exists (
    select 1
    from public.collaboration_project_members
    where project_id = target_project_id
      and profile_id = target_profile_id
      and membership_status in ('invited', 'accepted')
  ) then
    raise exception 'This profile already belongs to the project.';
  end if;

  raw_token := encode(extensions.gen_random_bytes(32), 'hex');

  insert into public.collaboration_project_invites (
    project_id,
    invited_by,
    invited_profile_id,
    invited_email,
    invite_token_hash,
    role,
    expires_at
  )
  values (
    target_project_id,
    current_user_id,
    target_profile_id,
    nullif(lower(btrim(target_email)), ''),
    encode(extensions.digest(raw_token, 'sha256'), 'hex'),
    target_role,
    timezone('utc', now()) + make_interval(days => greatest(1, least(expires_in_days, 30)))
  )
  returning id into new_invite_id;

  if target_profile_id is not null then
    insert into public.notifications (
      recipient_id,
      actor_id,
      type,
      project_id
    )
    values (
      target_profile_id,
      current_user_id,
      'project_invite',
      target_project_id
    );
  end if;

  insert into public.collaboration_activity (
    project_id,
    actor_id,
    activity_type,
    entity_type,
    entity_id,
    metadata
  )
  values (
    target_project_id,
    current_user_id,
    'member_invited',
    'invite',
    new_invite_id,
    jsonb_build_object('role', target_role)
  );

  return query select new_invite_id, raw_token;
end;
$$;

create or replace function public.leave_collaboration_project(target_project_id uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  current_user_id uuid := auth.uid();
  member_role text := public.collaboration_member_role(target_project_id, current_user_id);
  project_conversation_id uuid;
begin
  if member_role is null then
    raise exception 'You are not an active member of this project.';
  end if;

  if member_role = 'owner' then
    raise exception 'Transfer project ownership before leaving.';
  end if;

  update public.collaboration_project_members
  set membership_status = 'removed'
  where project_id = target_project_id
    and profile_id = current_user_id;

  select id into project_conversation_id
  from public.conversations
  where project_id = target_project_id
    and kind = 'project';

  delete from public.conversation_members
  where conversation_id = project_conversation_id
    and profile_id = current_user_id;

  insert into public.collaboration_activity (
    project_id,
    actor_id,
    activity_type,
    entity_type,
    entity_id
  )
  values (
    target_project_id,
    current_user_id,
    'member_left',
    'profile',
    current_user_id
  );
end;
$$;

