create or replace function public.moderate_report_v2(
  target_report_id uuid,
  next_status text,
  internal_note text default null,
  hide_target boolean default false,
  suspension_days integer default null
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  target_report public.reports%rowtype;
  target_profile_id uuid;
  notification_post_id uuid;
  notification_comment_id uuid;
  notification_conversation_id uuid;
  target_label text;
  target_location text;
  action_summary text;
begin
  if not public.is_app_admin(auth.uid(), 'moderator') then
    raise exception 'Administrator access required.';
  end if;
  if next_status not in ('open', 'reviewing', 'action_taken', 'dismissed') then
    raise exception 'Unsupported report status.';
  end if;
  if suspension_days is not null and suspension_days not between 1 and 90 then
    raise exception 'Suspension duration must be between 1 and 90 days.';
  end if;

  select * into target_report
  from public.reports
  where id = target_report_id
  for update;
  if target_report.id is null then
    raise exception 'Report not found.';
  end if;

  if target_report.target_type = 'profile' then
    target_profile_id := target_report.target_id;
  elsif target_report.target_type = 'post' then
    select owner_id into target_profile_id
    from public.posts where id = target_report.target_id;
  elsif target_report.target_type = 'comment' then
    select author_id into target_profile_id
    from public.comments where id = target_report.target_id;
  elsif target_report.target_type = 'message' then
    select sender_id into target_profile_id
    from public.messages where id = target_report.target_id;
  elsif target_report.target_type = 'project_invite' then
    select invited_by into target_profile_id
    from public.collaboration_project_invites where id = target_report.target_id;
  elsif target_report.target_type = 'share_link' then
    select owner_id into target_profile_id
    from public.share_links where id = target_report.target_id;
  end if;

  update public.reports
  set
    status = next_status,
    reviewed_by = auth.uid(),
    reviewed_at = timezone('utc', now()),
    target_hidden_at = case when hide_target then timezone('utc', now()) else target_hidden_at end
  where id = target_report_id;

  if nullif(btrim(internal_note), '') is not null then
    insert into public.report_admin_notes (report_id, author_id, body)
    values (target_report_id, auth.uid(), btrim(internal_note));
  end if;

  if target_report.target_type = 'profile' then
    target_profile_id := target_report.target_id;
    target_label := 'Your profile';
    target_location := 'Public profile';
    if hide_target then
      update public.profiles set deactivated_at = coalesce(deactivated_at, timezone('utc', now()))
      where id = target_report.target_id;
      action_summary := 'Your public profile was deactivated on MxTrove.';
    end if;
  elsif target_report.target_type = 'post' then
    select owner_id, title, id
    into target_profile_id, target_label, notification_post_id
    from public.posts where id = target_report.target_id;
    target_location := 'Public release “' || coalesce(target_label, 'Untitled release') || '”';
    if hide_target then
      update public.posts set hidden_at = timezone('utc', now()) where id = target_report.target_id;
      action_summary := 'The release was removed from MxTrove.';
    end if;
  elsif target_report.target_type = 'comment' then
    select comment.author_id, left(comment.body, 180), comment.id, comment.post_id,
           'Comment on “' || post.title || '”'
    into target_profile_id, target_label, notification_comment_id, notification_post_id, target_location
    from public.comments as comment
    join public.posts as post on post.id = comment.post_id
    where comment.id = target_report.target_id;
    if hide_target then
      update public.comments set deleted_at = coalesce(deleted_at, timezone('utc', now()))
      where id = target_report.target_id;
      action_summary := 'The comment was removed from MxTrove.';
    end if;
  elsif target_report.target_type = 'message' then
    select sender_id, conversation_id
    into target_profile_id, notification_conversation_id
    from public.messages where id = target_report.target_id;
    target_label := 'Direct message';
    target_location := 'Direct message conversation';
    if hide_target then
      update public.messages set deleted_at = coalesce(deleted_at, timezone('utc', now()))
      where id = target_report.target_id;
      action_summary := 'The message was removed from MxTrove.';
    end if;
  elsif target_report.target_type = 'project_invite' then
    select invited_by into target_profile_id
    from public.collaboration_project_invites where id = target_report.target_id;
    target_label := 'Project invitation';
    target_location := 'Collaboration invitation';
    if hide_target then
      update public.collaboration_project_invites
      set status = 'revoked', revoked_at = coalesce(revoked_at, timezone('utc', now()))
      where id = target_report.target_id and status = 'pending';
      action_summary := 'The project invitation was revoked.';
    end if;
  elsif target_report.target_type = 'share_link' then
    select owner_id into target_profile_id from public.share_links where id = target_report.target_id;
    target_label := 'Protected review link';
    target_location := 'Private sharing';
    if hide_target then
      update public.share_links
      set is_active = false, revoked_at = coalesce(revoked_at, timezone('utc', now()))
      where id = target_report.target_id;
      action_summary := 'The protected share link was revoked.';
    end if;
  end if;

  if suspension_days is not null and target_profile_id is not null then
    update public.profiles
    set suspended_until = timezone('utc', now()) + make_interval(days => suspension_days)
    where id = target_profile_id;
    action_summary := concat_ws(
      ' ',
      nullif(action_summary, ''),
      'The account was suspended for ' || suspension_days || case when suspension_days = 1 then ' day.' else ' days.' end
    );
  end if;

  if target_profile_id is not null
    and (hide_target or suspension_days is not null)
  then
    perform public.create_content_moderation_notification(
      target_profile_id,
      target_report.reason,
      target_report.target_type,
      coalesce(target_label, initcap(replace(target_report.target_type, '_', ' '))),
      coalesce(target_location, initcap(replace(target_report.target_type, '_', ' '))),
      coalesce(action_summary, 'A moderation action was taken on MxTrove.'),
      notification_post_id,
      notification_comment_id,
      notification_conversation_id,
      null
    );
  end if;
end;
$$;

create or replace function public.moderate_report(
  target_report_id uuid,
  next_status text,
  internal_note text default null,
  hide_target boolean default false
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  target_report public.reports%rowtype;
begin
  if not public.is_app_admin(auth.uid(), 'moderator') then
    raise exception 'Administrator access required.';
  end if;

  if next_status not in ('open', 'reviewing', 'action_taken', 'dismissed') then
    raise exception 'Unsupported report status.';
  end if;

  select * into target_report
  from public.reports
  where id = target_report_id
  for update;

  if target_report.id is null then
    raise exception 'Report not found.';
  end if;

  update public.reports
  set
    status = next_status,
    reviewed_by = auth.uid(),
    reviewed_at = timezone('utc', now()),
    target_hidden_at = case when hide_target then timezone('utc', now()) else target_hidden_at end
  where id = target_report_id;

  if nullif(btrim(internal_note), '') is not null then
    insert into public.report_admin_notes (report_id, author_id, body)
    values (target_report_id, auth.uid(), btrim(internal_note));
  end if;

  if hide_target and target_report.target_type = 'post' then
    update public.posts
    set hidden_at = timezone('utc', now())
    where id = target_report.target_id;
  elsif hide_target and target_report.target_type = 'comment' then
    update public.comments
    set deleted_at = coalesce(deleted_at, timezone('utc', now()))
    where id = target_report.target_id;
  elsif hide_target and target_report.target_type = 'message' then
    update public.messages
    set deleted_at = coalesce(deleted_at, timezone('utc', now()))
    where id = target_report.target_id;
  elsif hide_target and target_report.target_type = 'profile' then
    update public.profiles
    set deactivated_at = coalesce(deactivated_at, timezone('utc', now()))
    where id = target_report.target_id;
  end if;
end;
$$;

create or replace function public.prevent_admin_self_moderation_action()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  target_profile_id uuid;
begin
  if new.target_type = 'post' then
    select owner_id into target_profile_id
    from public.posts
    where id = new.target_id;
  elsif new.target_type = 'comment' then
    select author_id into target_profile_id
    from public.comments
    where id = new.target_id;
  end if;

  if target_profile_id = new.actor_id then
    raise exception 'Administrators cannot moderate their own content. Use the normal owner controls instead.';
  end if;

  return new;
end;
$$;

create or replace function public.prevent_admin_self_report_moderation()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  target_profile_id uuid;
begin
  if new.reviewed_by is null then
    return new;
  end if;

  if new.target_type = 'profile' then
    target_profile_id := new.target_id;
  elsif new.target_type = 'post' then
    select owner_id into target_profile_id from public.posts where id = new.target_id;
  elsif new.target_type = 'comment' then
    select author_id into target_profile_id from public.comments where id = new.target_id;
  elsif new.target_type = 'message' then
    select sender_id into target_profile_id from public.messages where id = new.target_id;
  elsif new.target_type = 'project_invite' then
    select invited_by into target_profile_id
    from public.collaboration_project_invites where id = new.target_id;
  elsif new.target_type = 'share_link' then
    select owner_id into target_profile_id from public.share_links where id = new.target_id;
  end if;

  if target_profile_id = new.reviewed_by then
    raise exception 'Administrators cannot moderate their own content or account.';
  end if;

  return new;
end;
$$;

create or replace function public.protect_hidden_profile_location()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  location_is_public boolean;
begin
  select coalesce(show_location, true)
  into location_is_public
  from public.profile_privacy_settings
  where profile_id = new.id;

  if location_is_public = false and new.location is not null then
    update public.profile_privacy_settings
    set private_location = new.location
    where profile_id = new.id;
    new.location := null;
  end if;

  return new;
end;
$$;

create or replace function public.publish_single_version(version_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  current_user_id uuid := auth.uid();
  target_song_id uuid;
  target_preview_asset_id uuid;
  target_post_id uuid;
  existing_published_count integer;
  target_preview_access text;
  target_preview_type text;
  event_name text;
begin
  select song_id, preview_asset_id
  into target_song_id, target_preview_asset_id
  from public.song_versions
  where id = version_id;

  if target_song_id is null then
    raise exception 'Song version not found.';
  end if;

  if not exists (
    select 1
    from public.songs
    where id = target_song_id
      and owner_id = current_user_id
  ) then
    raise exception 'Only the song owner can publish this version.';
  end if;

  if target_preview_asset_id is null then
    raise exception 'A public preview asset is required before publishing.';
  end if;

  select access_mode, asset_type
  into target_preview_access, target_preview_type
  from public.assets
  where id = target_preview_asset_id;

  if target_preview_access <> 'public' or target_preview_type <> 'audio_preview' then
    raise exception 'The selected preview asset is not publicly playable.';
  end if;

  select post_id into target_post_id
  from public.single_posts
  where song_id = target_song_id;

  if target_post_id is null then
    raise exception 'No single post exists for this song yet.';
  end if;

  select count(*)
  into existing_published_count
  from public.song_versions
  where song_id = target_song_id
    and is_published = true
    and id <> version_id;

  event_name := case when existing_published_count > 0 then 'single_update' else 'single_release' end;

  update public.song_versions
  set
    is_published = true,
    published_at = coalesce(published_at, timezone('utc', now())),
    updated_at = timezone('utc', now())
  where id = version_id;

  update public.single_posts
  set featured_version_id = version_id
  where post_id = target_post_id;

  update public.posts
  set
    visibility = 'public',
    is_published = true,
    published_at = coalesce(published_at, timezone('utc', now())),
    activity_at = timezone('utc', now()),
    updated_at = timezone('utc', now())
  where id = target_post_id;

  insert into public.feed_events (actor_id, post_id, song_version_id, event_type)
  values (current_user_id, target_post_id, version_id, event_name);

  insert into public.notifications (recipient_id, actor_id, type, post_id, song_version_id)
  select
    follows.follower_id,
    current_user_id,
    'single_version',
    target_post_id,
    version_id
  from public.follows
  where follows.followed_id = current_user_id
    and follows.follower_id <> current_user_id;
end;
$$;

create or replace function public.queue_notification_for_push()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  preferences public.notification_preferences%rowtype;
begin
  if new.recipient_id is null or new.recipient_id = new.actor_id then
    return new;
  end if;

  select *
  into preferences
  from public.notification_preferences
  where profile_id = new.recipient_id;

  if preferences.profile_id is null then
    insert into public.notification_preferences (profile_id)
    values (new.recipient_id)
    on conflict (profile_id) do nothing;

    select *
    into preferences
    from public.notification_preferences
    where profile_id = new.recipient_id;
  end if;

  if public.notification_type_push_enabled(preferences, new.type) then
    if exists (
      select 1
      from public.push_subscriptions
      where push_subscriptions.profile_id = new.recipient_id
        and push_subscriptions.is_active = true
    ) then
      insert into public.push_delivery_queue (notification_id, recipient_id)
      values (new.id, new.recipient_id);
    end if;
  end if;

  return new;
end;
$$;

