create or replace function public.release_protected_media_asset(target_asset_id uuid)
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  asset public.protected_media_assets%rowtype;
  storage_key_to_delete text;
  is_attachment boolean;
begin
  select *
  into asset
  from public.protected_media_assets
  where id = target_asset_id
  for update;

  if asset.id is null then
    return null;
  end if;

  storage_key_to_delete := asset.storage_key;
  is_attachment := asset.purpose in ('message_audio', 'message_image', 'message_document');

  update public.protected_media_quotas
  set
    reserved_bytes = greatest(0, reserved_bytes - case when asset.status in ('reserved', 'processing') then asset.reserved_bytes else 0 end),
    attachment_reserved_bytes = greatest(
      0,
      attachment_reserved_bytes - case
        when asset.status in ('reserved', 'processing') and is_attachment then asset.reserved_bytes
        else 0
      end
    ),
    used_bytes = greatest(0, used_bytes - case when asset.status = 'ready' then coalesce(asset.bytes, 0) else 0 end),
    attachment_used_bytes = greatest(
      0,
      attachment_used_bytes - case
        when asset.status = 'ready' and is_attachment then coalesce(asset.bytes, 0)
        else 0
      end
    )
  where profile_id = asset.owner_id;

  update public.protected_media_assets
  set
    status = 'deleted',
    deleted_at = timezone('utc', now()),
    reserved_bytes = 0
  where id = target_asset_id;

  return storage_key_to_delete;
end;
$$;

create or replace function public.remove_project_member(
  target_project_id uuid,
  target_profile_id uuid
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  current_user_id uuid := auth.uid();
  actor_role text := public.collaboration_member_role(target_project_id, current_user_id);
  target_role text := public.collaboration_member_role(target_project_id, target_profile_id);
  project_conversation_id uuid;
begin
  if actor_role not in ('owner', 'admin') then
    raise exception 'You cannot manage members for this project.';
  end if;

  if target_role is null then
    raise exception 'Project member not found.';
  end if;

  if target_role = 'owner' then
    raise exception 'The project owner cannot be removed.';
  end if;

  if actor_role = 'admin' and target_role = 'admin' then
    raise exception 'Admins cannot remove other admins.';
  end if;

  update public.collaboration_project_members
  set
    membership_status = 'removed',
    updated_at = timezone('utc', now())
  where project_id = target_project_id
    and profile_id = target_profile_id;

  select id into project_conversation_id
  from public.conversations
  where project_id = target_project_id
    and kind = 'project';

  delete from public.conversation_members
  where conversation_id = project_conversation_id
    and profile_id = target_profile_id;

  insert into public.notifications (recipient_id, actor_id, type, project_id)
  values (target_profile_id, current_user_id, 'project_member_removed', target_project_id);

  insert into public.collaboration_activity (
    project_id,
    actor_id,
    activity_type,
    entity_type,
    entity_id
  )
  values (
    target_project_id,
    current_user_id,
    'member_removed',
    'profile',
    target_profile_id
  );
end;
$$;

create or replace function public.remove_public_content_for_moderation(
  target_content_type text,
  target_content_id uuid,
  removal_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  normalized_reason text := lower(btrim(coalesce(removal_reason, '')));
  target_post public.posts%rowtype;
  target_comment public.comments%rowtype;
  target_snapshot jsonb;
  action_id uuid;
  action_time timestamptz := timezone('utc', now());
  recipient_id uuid;
  target_label text;
  target_location text;
  target_post_id uuid;
  target_comment_id uuid;
begin
  if not public.is_app_admin(auth.uid(), 'moderator') then
    raise exception 'Administrator access required.';
  end if;

  if target_content_type not in ('post', 'comment') then
    raise exception 'Only public posts and comments can be removed here.';
  end if;

  if normalized_reason not in ('copyright', 'hate', 'harassment', 'sexual_content', 'illegal_content', 'spam', 'other') then
    raise exception 'Choose a valid moderation reason.';
  end if;

  if target_content_type = 'post' then
    select post.* into target_post
    from public.posts as post
    where post.id = target_content_id
    for update;

    if target_post.id is null then
      raise exception 'The release could not be found.';
    end if;
    if target_post.visibility <> 'public' or not target_post.is_published then
      raise exception 'Private and unpublished releases are outside the moderation dashboard.';
    end if;
    if target_post.hidden_at is not null then
      raise exception 'This release has already been removed.';
    end if;
    target_snapshot := jsonb_build_object(
      'title', target_post.title,
      'owner_id', target_post.owner_id,
      'post_type', target_post.post_type,
      'visibility', target_post.visibility
    );
    recipient_id := target_post.owner_id;
    target_label := target_post.title;
    target_location := 'Public release “' || target_post.title || '”';
    target_post_id := target_post.id;

    update public.posts
    set hidden_at = action_time,
        activity_at = action_time
    where id = target_post.id;
  else
    select comment.* into target_comment
    from public.comments as comment
    join public.posts as post on post.id = comment.post_id
    where comment.id = target_content_id
      and post.visibility = 'public'
      and post.is_published
      and post.hidden_at is null
    for update of comment;

    if target_comment.id is null then
      raise exception 'The public comment could not be found.';
    end if;
    if target_comment.deleted_at is not null then
      raise exception 'This comment has already been removed.';
    end if;
    target_snapshot := jsonb_build_object(
      'body', target_comment.body,
      'author_id', target_comment.author_id,
      'post_id', target_comment.post_id,
      'parent_comment_id', target_comment.parent_comment_id
    );
    recipient_id := target_comment.author_id;
    target_label := left(target_comment.body, 180);
    target_post_id := target_comment.post_id;
    target_comment_id := target_comment.id;
    select 'Comment on “' || post.title || '”'
    into target_location
    from public.posts as post
    where post.id = target_comment.post_id;

    update public.comments
    set deleted_at = action_time,
        updated_at = action_time
    where id = target_comment.id;
  end if;

  insert into public.admin_moderation_actions (
    actor_id,
    target_type,
    target_id,
    action,
    reason,
    target_snapshot
  )
  values (
    auth.uid(),
    target_content_type,
    target_content_id,
    'remove',
    normalized_reason,
    target_snapshot
  )
  returning id into action_id;

  perform public.create_content_moderation_notification(
    recipient_id,
    normalized_reason,
    target_content_type,
    target_label,
    target_location,
    case
      when target_content_type = 'post' then 'The release was removed from MxTrove.'
      else 'The comment was removed from MxTrove.'
    end,
    target_post_id,
    target_comment_id,
    null,
    action_id
  );

  update public.reports
  set status = 'action_taken',
      reviewed_by = auth.uid(),
      reviewed_at = action_time,
      target_hidden_at = action_time
  where reports.target_type = target_content_type
    and reports.target_id = target_content_id
    and reports.status in ('open', 'reviewing');

  return jsonb_build_object(
    'action_id', action_id,
    'target_type', target_content_type,
    'target_id', target_content_id,
    'removed_at', action_time
  );
end;
$$;

