create or replace function public.reorder_project_tracks(
  target_project_id uuid,
  ordered_track_ids uuid[]
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  current_user_id uuid := auth.uid();
  existing_count integer;
  requested_count integer;
begin
  if not public.can_edit_collaboration_project(target_project_id, current_user_id) then
    raise exception 'You cannot reorder this project.';
  end if;

  select count(*) into existing_count
  from public.collaboration_project_tracks
  where project_id = target_project_id;

  select count(distinct track_id) into requested_count
  from unnest(ordered_track_ids) as track_id;

  if existing_count <> requested_count or exists (
    select 1
    from unnest(ordered_track_ids) as requested(track_id)
    left join public.collaboration_project_tracks as track
      on track.id = requested.track_id
      and track.project_id = target_project_id
    where track.id is null
  ) then
    raise exception 'The supplied track order is incomplete or invalid.';
  end if;

  -- Move through negative values first to preserve the unique project/track-number constraint.
  update public.collaboration_project_tracks
  set track_number = -track_number
  where project_id = target_project_id;

  update public.collaboration_project_tracks as track
  set track_number = requested.position
  from unnest(ordered_track_ids) with ordinality as requested(track_id, position)
  where track.id = requested.track_id
    and track.project_id = target_project_id;

  insert into public.collaboration_activity (
    project_id,
    actor_id,
    activity_type,
    entity_type,
    entity_id,
    metadata
  )
  values (
    target_project_id,
    current_user_id,
    'track_reordered',
    'project',
    target_project_id,
    jsonb_build_object('track_ids', ordered_track_ids)
  );
end;
$$;

create or replace function public.replace_release_credits(
  target_post_id uuid,
  next_credits jsonb
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not exists (
    select 1
    from public.posts
    where id = target_post_id
      and owner_id = auth.uid()
  ) then
    raise exception 'Release not found.';
  end if;

  if jsonb_typeof(coalesce(next_credits, '[]'::jsonb)) <> 'array'
    or jsonb_array_length(coalesce(next_credits, '[]'::jsonb)) > 40 then
    raise exception 'Credits must be an array with at most 40 entries.';
  end if;

  delete from public.post_credits
  where post_id = target_post_id;

  insert into public.post_credits (
    post_id,
    profile_id,
    display_name,
    role,
    position
  )
  select
    target_post_id,
    credit.profile_id,
    btrim(credit.display_name),
    credit.role,
    credit.position
  from jsonb_to_recordset(coalesce(next_credits, '[]'::jsonb))
    as credit(profile_id uuid, display_name text, role text, position integer);
end;
$$;

create or replace function public.replace_release_external_links(
  target_post_id uuid,
  next_links jsonb
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not exists (
    select 1
    from public.posts
    where id = target_post_id
      and owner_id = auth.uid()
  ) then
    raise exception 'Release not found.';
  end if;

  if jsonb_typeof(coalesce(next_links, '[]'::jsonb)) <> 'array'
    or jsonb_array_length(coalesce(next_links, '[]'::jsonb)) > 20 then
    raise exception 'External links must be an array with at most 20 entries.';
  end if;

  delete from public.post_external_links
  where post_id = target_post_id;

  insert into public.post_external_links (
    post_id,
    platform,
    label,
    url,
    position
  )
  select
