    link.platform,
    btrim(link.label),
    btrim(link.url),
    link.position
  from jsonb_to_recordset(coalesce(next_links, '[]'::jsonb))
    as link(platform text, label text, url text, position integer);

  update public.posts
  set release_url = (
    select url
    from public.post_external_links
    where post_id = target_post_id
    order by position
    limit 1
  )
  where id = target_post_id;
end;
